module tb;
    // Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    reg slowena;
    wire [3:0] q;

    // Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .slowena(slowena),
        .q(q)
    );

    // Stimulus & self-checking:
    integer errors = 0;
    initial begin
        // Apply stimulus and verify outputs
        clk = 0;
        reset = 0;
        slowena = 0;

        // Test reset
        reset = 1;
        #10;
        if (q !== 4'b0000) begin
            errors = errors + 1;
        end
        reset = 0;

        // Test increment on every clock cycle
        for (int i = 0; i < 10; i++) begin
            #5 clk = 1;
            #5 clk = 0;
            if (slowena) begin
                #5 clk = 1;
                #5 clk = 0;
            end
            if (q !== $bitstoreg(i)) begin
                errors = errors + 1;
            end
        end

        // Test pause
        slowena = 1;
        #10;
        if (q !== $bitstoreg(9)) begin
            errors = errors + 1;
        end
        slowena = 0;

        // Test reset after pause
        reset = 1;
        #10;
        if (q !== 4'b0000) begin
            errors = errors + 1;
        end
        reset = 0;

        // Check if all tests pass
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
```

Note: The `$bitstoreg(i)` function is used to convert the integer `i` to a 4-bit binary value. This is used to compare the output `q` with the expected value for each test case.

